from pathlib import Path
import re

root = Path('.')

checkpoint = root / 'docs/project/current/dev/DEV-poster-grid-smoothness.md'
text = checkpoint.read_text()
status_re = re.compile(r'\*\*Active — .*?\*\*\n\n- \*\*Work ID\*\*:', re.S)
status_new = '''**Active — Build261 is target-device tested. Home vertical scrolling now reaches the intended 120 Hz cadence and is noticeably better, but occasional long-frame tails remain. Library Build261 logs prove two concurrent layers: high-speed SwiftUI cell lifecycle churn is a direct long-gap contributor, while a separate untracked long-frame source remains even with fixed item count. Build261 / 0.14.94 is the current diagnostic authority, Draft PR #270, not stable.**\n\n- **Work ID**:'''
text, n = status_re.subn(status_new, text, count=1)
assert n == 1, 'checkpoint status replace failed'
replacements = {
    r'^- \*\*Working branch\*\*:.*$': '- **Working branch**: `perf/poster-grid-long-frame-build261`',
    r'^- \*\*Draft PR\*\*:.*$': '- **Draft PR**: #270',
    r'^- \*\*Superseded PRs\*\*:.*$': '- **Superseded PRs**: #268 Build260 diagnostic completed and closed without merge; #267 Build259 A/B completed and closed without merge; #266 Build258 diagnostic closed without merge; #265 Build257 fallback closed without merge; #259 stale Build243 poster branch retained only as historical diagnostic evidence',
    r'^- \*\*Current branch / PR head\*\*:.*$': '- **Current branch / PR head**: `e552bebd072a915e6cb10d591d704a5a3c342406`',
    r'^- \*\*Current candidate\*\*:.*$': '- **Current candidate**: OnePlayer `0.14.94 (261)`; directly parented from Build260 exact source `b9a5de5255650f04e312e117f47453122de56adc`; CI/IPA verified and target-device tested 2026-08-30; not stable',
}
for pattern, replacement in replacements.items():
    text, n = re.subn(pattern, replacement, text, count=1, flags=re.M)
    assert n == 1, f'checkpoint line replace failed: {pattern}'
section_marker = '## Build229 latest target-device result / candidate identity guard — 2026-08-29'
assert section_marker in text
assert '## Build261 target-device long-frame attribution — 2026-08-30' not in text
section = '''## Build261 target-device long-frame attribution — 2026-08-30\n\nBuild261 / OnePlayer **0.14.94 (261)** exact source `e552bebd072a915e6cb10d591d704a5a3c342406`, branch `perf/poster-grid-long-frame-build261`, Draft PR #270, directly extends Build260 with two narrowly-scoped changes: Home reuses its existing real ancestor vertical `UIScrollView` observer to request `CAFrameRateRange(minimum: 80, maximum: deviceMaximum, preferred: deviceMaximum)` only during real drag/deceleration and logs `HomeScrollCadence`; Library preserves Build260 cadence sampling and attributes every `>=12.5 ms` display gap to same-frame cell appear/disappear churn, load-ahead, item-count change, offset-update count, or `untracked`. Exact Build260→261 delta is five paths: AppIdentity, Home scroll observer, poster cadence diagnostics, Build261 changelog and cadence checker. No `decelerationRate`, Home carousel interaction/presentation, `EmbyHomeCoreV3`, `EmbyPosterGrid.swift`, Grid geometry, Search semantics, image/cache policy, Player/MPV/PiP, UnifiedTransport, STRM/302/115/CDN or Deployment Target behavior changes.\n\nBuild261 Xcode 16.4 run/job **`33310546942 / 99254688579`** succeeded. Artifact `OnePlayer-0.14.94-build261-long-frame`, ID **`9731868664`**, digest `sha256:bf9dab2b5acab5befc5516ce7bb5e920e9e01277caa757f137173c9c8b33c14d`; IPA SHA-256 `d5f719c2cbcd8df4908f9f7ecfd9b5c5db88288cdf16cd45b09a263966511724`; package `com.embyplayerlab.app`, `0.14.94 (261)`, MinOS 15.0. Exact five-path scope, dedicated checker, `git diff --check`, Release compile, package identity, MinOS and artifact upload all passed.\n\nTarget-device result from `OnePlayer-App-1788093610.log` on iPhone 15 Pro Max / iOS 17.0:\n\n- **Home improved:** user reports Home is better than before. Across 12 Home motion sessions / 3,309 display samples, every session reports display p50/p95 `8.34 ms`; 9/12 sessions never exceed `16.67 ms`. Remaining long tails are max `50.31 / 36.24 / 76.94 ms`. The first two occur immediately after Home refresh / a burst of HTTP requests; the 76.94 ms sample has no current Home attribution. High refresh is effective but Home is not stable.\n- **Library aggregate:** 49 sessions / 9,573 display samples; `356` gaps `>=12.5 ms`, `94` gaps `>=25 ms`, `57` gaps `>=33.3 ms`, max `175.79 ms`. `193` long gaps overlap cell lifecycle churn; `162` (`45.5%`) are completely `untracked` by current cell/load-ahead/item-count categories. Tracked categories can overlap, so do not sum them as exclusive percentages.\n- **Fixed-count evidence:** sessions with no item-count changes still contain `170` long gaps, `41 >=25 ms`, `23 >=33.3 ms`, max `112.97 ms`. Pagination/item-count diff is therefore not sufficient.\n- **Cell-churn proof:** one fixed `600→600`, 4.74 s fast-scroll session records `73` long gaps; `67` overlap cell churn, with `33 >=25 ms`, `16 >=33.3 ms`, max `70.70 ms`, and up to 12 cell appears + 12 disappears within one long-gap interval. High-speed SwiftUI cell lifecycle churn is a proven contributor.\n- **Second-source proof:** fixed `60→60` pure scrolling can still produce a `33.82 ms` long gap with zero cell churn/load-ahead/item-count changes in that gap. A separate main-thread/rendering source remains.\n\n**Controlling interpretation:** the EX comparison should now be framed as long-frame-tail elimination, not merely requesting 120 Hz. Library has at least two layers: high-speed cell lifecycle churn plus an untracked long-frame source. Do not claim pagination is the root cause, do not tune native scroll physics by guess, and do not wholesale-replace the Grid before the severe `untracked` gaps are isolated. Home's 120 Hz request is a real improvement but its remaining occasional tails also need attribution.\n\n**Evidence:** Build261 Code written ✅ / CI passed ✅ / IPA produced ✅ / target-device tested ✅ / Home improvement confirmed ✅ / Home stable ❌ / Library cell-churn contribution proven ✅ / separate untracked long-frame source proven ✅ / overall smoothness stable ❌.\n\n**Next exact action:** before a behavioral Grid rewrite, extend severe-gap attribution so `>=25 ms` / `>=33.3 ms` gaps can distinguish cell lifecycle work from image-main-thread publication / SwiftUI update-layout-presentation work and other current owners. Use the same exact Build261 lineage; do not add delay/debounce/timer/watchdog or change scroll physics. For Home, correlate the remaining long gaps with refresh/model/image publication rather than changing the now-effective refresh request.\n\n'''
text = text.replace(section_marker, section + section_marker, 1)
checkpoint.write_text(text)

project = root / 'docs/project/PROJECT_STATE.md'
text = project.read_text()
text, n = re.subn(r'^_Last updated .*?_$', '_Last updated 2026-08-30: Build261 / 0.14.94 is target-device tested. Home vertical motion now normally runs at 8.34 ms display cadence and is visibly better, but occasional 36–77 ms long tails remain. Library long-gap attribution proves high-speed cell lifecycle churn is one direct contributor while a separate untracked fixed-item source remains; 120 Hz request alone is not the final EX-level smoothness solution. Build261 Draft PR #270 remains unmerged/not stable. Search Build256 and P0 playback/transport contracts remain protected._', text, count=1, flags=re.M)
